-- Sale and Supply of Alcohol Act 2012 and Gambling Act 2003 read on legislation.govt.nz on 26 Nov 2026 (Framework v0.4, Appendix C.2).
-- Adds two source register rows and updates only the two items created in 20261126010000 (guarded: runs only while their old wording is still there).
insert into public.legal_sources (key,name,kind,provisions_read,version_and_date_read,status,url,notes,checked_on)
select v.* from (values
($q$SSAA12$q$,$q$Sale and Supply of Alcohol Act 2012 (2012 No 120)$q$,$q$legislation$q$,$q$section 5(1) definition of "sell", and sections 22, 28, 137, 145 and 146 read in full; the rest of the Act (offences, conditions, who applies when a hall is hired out) not read$q$,$q$latest version as at 5 April 2026; read on legislation.govt.nz in Chrome, 26 Nov 2026$q$,$q$Verified – primary source (Act), sections named only$q$,$q$https://www.legislation.govt.nz/act/public/2012/120/en/latest/$q$,null::text,date '2026-11-26'),
($q$GAMBA03$q$,$q$Gambling Act 2003 (2003 No 51)$q$,$q$legislation$q$,$q$section 4 definitions of "society" and the start of "authorised purpose"; sections 22 to 28 read in full; the rest of the Act not read$q$,$q$latest version as at 6 June 2026; read on legislation.govt.nz in Chrome, 26 Nov 2026$q$,$q$Verified – primary source (Act), sections named only$q$,$q$https://www.legislation.govt.nz/act/public/2003/51/en/latest/$q$,null::text,date '2026-11-26')
) as v(key,name,kind,provisions_read,version_and_date_read,status,url,notes,checked_on)
where not exists (select 1 from public.legal_sources s where s.key=v.key);

update public.compliance_items set
 notes = replace(notes, 'Partly verified (Ministry page read in full; the Act itself not yet read; the page is archived and dated 2020)', 'Partly verified (Act sections 5, 22, 28, 137, 145 and 146 read in full 26 Nov 2026; the Ministry page, archived and dated 2020, covers the rest)'),
 legal_basis_detail = $q$Apply to the local council's licensing committee at least 20 working days before the event. The committee may consider a later application if the need could not reasonably have been foreseen (section 137). Under the Act, charging an entry fee or ticket price, or asking or suggesting a koha, counts as selling alcohol. A special licence can be held by a person aged 20 or over, a body corporate, a company, or a board or body authorised by another enactment. Whether alcohol is allowed on the marae at all is a matter of tikanga and kawa, not law. Some parts (series of events, fees, Police reports) still rest on the Ministry page, which is archived and dated 2020. Partly confirmed; part of this is still being checked.$q$,
 source_keys = array['MOJSL','SSAA12']
where name = $q$Special licence arranged for any event where alcohol is sold, or an entry fee or koha is charged$q$ and legal_basis_detail like '%the Act itself has not yet been read%';

update public.compliance_items set
 notes = replace(notes, 'Partly verified (DIA page read in full; whether a marae counts as a society is not yet confirmed)', 'Partly verified (DIA page and Gambling Act sections 4 and 22 to 28 read in full 26 Nov 2026; whether each marae counts as a society depends on its legal structure)'),
 legal_basis_detail = $q$Class 1 (prizes and turnover each up to $500) needs no licence. Class 2 (prizes up to $5,000, turnover up to $25,000) needs no licence but can be run only by a society: an incorporated society, a board incorporated under the Charitable Trusts Act 1957, or a non-profit company set up for authorised purposes. Above $5,000 in prizes it is class 3 and needs a licence held by a society. A marae that is not one of these kinds of society, for example an unincorporated committee, cannot run class 2 or 3, and class 1 is open to others only if the turnover goes back to the winners as prizes. Nobody can be paid or take commission for running it, except a housie caller or a society's authorised representative. Net proceeds must go to authorised purposes. Partly confirmed; part of this is still being checked.$q$,
 source_keys = array['DIAGC','GAMBA03']
where name = $q$Raffles and housie kept within the Department of Internal Affairs limits$q$ and legal_basis_detail like '%still to be confirmed%';
